import express from 'express';

export function createApp(db) {
  const app = express();

  app.use((req, res, next) => {
    express.json()(req, res, (err) => {
      if (err) return res.status(400).json({ error: 'Invalid JSON' });
      next();
    });
  });

  app.param('id', (req, res, next, value) => {
    const id = Number(value);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'id must be a positive integer' });
    }
    req.todoId = id;
    next();
  });

  app.post('/todos', (req, res) => {
    const body = (req.body && typeof req.body === 'object' && !Array.isArray(req.body)) ? req.body : {};
    const { title, done = false } = body;

    if (typeof title !== 'string' || title.trim().length === 0) {
      return res.status(400).json({ error: 'title is required' });
    }
    if (title.length > 200) {
      return res.status(400).json({ error: 'title must be 200 characters or less' });
    }
    if ('done' in body && typeof body.done !== 'boolean') {
      return res.status(400).json({ error: 'done must be a boolean' });
    }

    const now = new Date().toISOString();
    const result = db.prepare(
      'INSERT INTO todos (title, done, createdAt, updatedAt) VALUES (?, ?, ?, ?)'
    ).run(title.trim(), done ? 1 : 0, now, now);

    const todo = db.prepare('SELECT * FROM todos WHERE id = ?').get(result.lastInsertRowid);
    return res.status(201).json(format(todo));
  });

  app.get('/todos', (req, res) => {
    const { done } = req.query;
    let todos;
    if (done === 'true') {
      todos = db.prepare('SELECT * FROM todos WHERE done = 1').all();
    } else if (done === 'false') {
      todos = db.prepare('SELECT * FROM todos WHERE done = 0').all();
    } else {
      todos = db.prepare('SELECT * FROM todos').all();
    }
    return res.json(todos.map(format));
  });

  app.get('/todos/:id', (req, res) => {
    const todo = db.prepare('SELECT * FROM todos WHERE id = ?').get(req.todoId);
    if (!todo) return res.status(404).json({ error: 'Todo not found' });
    return res.json(format(todo));
  });

  app.put('/todos/:id', (req, res) => {
    const existing = db.prepare('SELECT * FROM todos WHERE id = ?').get(req.todoId);
    if (!existing) return res.status(404).json({ error: 'Todo not found' });

    const body = (req.body && typeof req.body === 'object' && !Array.isArray(req.body)) ? req.body : {};
    const { title, done } = body;

    if (title !== undefined) {
      if (typeof title !== 'string' || title.trim().length === 0) {
        return res.status(400).json({ error: 'title is required' });
      }
      if (title.length > 200) {
        return res.status(400).json({ error: 'title must be 200 characters or less' });
      }
    }
    if (done !== undefined && typeof done !== 'boolean') {
      return res.status(400).json({ error: 'done must be a boolean' });
    }

    const updatedTitle = title !== undefined ? title.trim() : existing.title;
    const updatedDone = done !== undefined ? (done ? 1 : 0) : existing.done;
    const now = new Date().toISOString();

    db.prepare('UPDATE todos SET title = ?, done = ?, updatedAt = ? WHERE id = ?')
      .run(updatedTitle, updatedDone, now, req.todoId);

    const todo = db.prepare('SELECT * FROM todos WHERE id = ?').get(req.todoId);
    return res.json(format(todo));
  });

  app.delete('/todos/:id', (req, res) => {
    const existing = db.prepare('SELECT * FROM todos WHERE id = ?').get(req.todoId);
    if (!existing) return res.status(404).json({ error: 'Todo not found' });
    db.prepare('DELETE FROM todos WHERE id = ?').run(req.todoId);
    return res.status(204).send();
  });

  return app;
}

function format(todo) {
  return {
    id: todo.id,
    title: todo.title,
    done: todo.done === 1,
    createdAt: todo.createdAt,
    updatedAt: todo.updatedAt,
  };
}

